solution.code:
#include <stdio.h>

int main() {
    for (int i = 1; i <= 3; i++) {
        for (int s = 0; s < 3 - i; s++) printf(" ");
        for (int k = 0; k < 2 * i - 1; k++) printf("*");
        printf("\n");
    }
    return 0;
}
